/* From Uiverse.io by javadpg - Tags: card, hover, stitched, transition, css, card hover */
.__UIV_SCOPE__ .card {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
  position: relative;
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 300px;
  height: 350px;
  border-radius: 6px;
  transition: .3s;
  background-color: #000;
}

.__UIV_SCOPE__ .card-p {
  position: absolute;
  text-align: center;
}

.__UIV_SCOPE__ .card::after {
  content: "";
  position: absolute;
  z-index: -6;
  border-radius: 6px;
  width: 320px;
  height: 370px;
  background-color: #8EC5FC;
  transition: .7s;
  background-image: linear-gradient(62deg, #8EC5FC 0%, #E0C3FC 100%);
}

.__UIV_SCOPE__ .card-countent {
  padding: 20px;
  text-align: center;
  color: transparent;
  transition: all .7s;
  opacity: 0;
}

.__UIV_SCOPE__ .card:hover {
  transition: .7s;
  transform: rotate(180deg);
}

.__UIV_SCOPE__ .card:hover > .card-p {
  color: transparent;
}

.__UIV_SCOPE__ .card:hover > .card-countent {
  opacity: 1;
  color: #000;
  transform: rotate(-180deg);
}
